import Foundation
import SwiftUI
import Testing
@testable import SwitchyardDesktopKit

private func highlighted(_ toml: String) -> AttributedString {
    TOMLHighlighter.highlight(toml, font: RouterTheme.mono(10))
}

private func color(of substring: String, in attributed: AttributedString) -> Color? {
    guard let range = attributed.range(of: substring) else { return nil }
    return attributed[range].foregroundColor
}

@Test func highlighterKeepsEveryLineOfTheGeneratedFile() {
    let toml = """
        # Generated by switchyard-desktop.
        schema_version = 1

        [targets.docs]
        id = "gpt-5.3-codex-spark"
        """

    let output = String(highlighted(toml).characters)

    #expect(output.contains("# Generated by switchyard-desktop."))
    #expect(output.contains("[targets.docs]"))
    #expect(output.contains("id = \"gpt-5.3-codex-spark\""))
}

@Test func highlighterColorsCommentsTablesAndStringsApart() {
    let attributed = highlighted("""
        # comment line
        [routes.main]
        id = "switchyard-desktop"
        """)

    let comment = color(of: "# comment line", in: attributed)
    let table = color(of: "[routes.main]", in: attributed)
    let string = color(of: "\"switchyard-desktop\"", in: attributed)
    let key = color(of: "id = ", in: attributed)

    #expect(table == RouterTheme.accent)
    #expect(comment != table)
    #expect(string != table)
    #expect(string != key)
}

@Test func highlighterTreatsALiteralBlockAsOneString() {
    let attributed = highlighted("""
        prompt = '''
        - docs: READMEs and comments.
        [not a table]
        '''
        id = "switchyard-desktop"
        """)

    // A line inside the block must not be mistaken for a table header.
    #expect(color(of: "[not a table]", in: attributed) != RouterTheme.accent)
    #expect(color(of: "\"switchyard-desktop\"", in: attributed) != nil)
}
